style.css:
/* ==UserStyle==
@name         Nitro Type Purple Prompt Theme
@namespace    userstyles
@version      1.5.0
@description  Purple race prompt only, hides WPM/accuracy, no full dark mode
==/UserStyle== */

/* Purple styling ONLY for the race text prompt */
[class^="dash-copy"], [class*="raceText"] {
  background-color: #2a003f !important; /* Deep purple background */
  color: #e0b3ff !important;            /* Soft lavender text */
  font-size: 1.2em !important;
  padding: 15px;
  border-radius: 10px;
  box-shadow: 0 0 10px rgba(128, 0, 128, 0.4); /* Purple glow */
  border: none !important;
}

/* Completely hide WPM and accuracy */
[class*="wpm"], [class*="accuracy"], [class*="stats"] {
  display: none !important;
}
